p=mk("1000.00"); process_refund_request(p,"600.00","u",T0,approved_by="boss"); print("approved",p.refunded_amount)
# idempotency
p=mk(); process_refund_request(p,"10.00","u",T0,idempotency_key="k1"); process_refund_request(p,"10.00","u",T0,idempotency_key="k1"); print("idem",p.refunded_amount)
